const sales = $json || {};

function getUpstreamValue(nodeName, key) {
  try {
    const item = $(nodeName).first().json;
    return String(item[key] || '').trim();
  } catch (e) {
    return '';
  }
}

return [{
  json: {
    opportunity_id: getUpstreamValue('Verify Fit', 'opportunity_id'),
    lead_id: getUpstreamValue('Verify Fit', 'lead_id'),
    company_id: getUpstreamValue('Verify Fit', 'company_id') || String($json.company_id || 'COMP001'),
    session_id: getUpstreamValue('Verify Fit', 'session_id') || String($json.session_id || ''),
    customer_name: getUpstreamValue('Verify Fit', 'customer_name'),
    email: getUpstreamValue('Verify Fit', 'email'),
    phone: getUpstreamValue('Verify Fit', 'phone'),
    requested_service: getUpstreamValue('Verify Fit', 'requested_service') || 'Cloud Security Assessment',

    intent: sales.intent || 'sales',
    business_need: sales.business_need || '',
    pain_points: sales.pain_points || '',
    decision_criteria: sales.decision_criteria || '',
    stakeholders: sales.stakeholders || '',
    matched_solution: sales.matched_solution || '',
    objection_type: sales.objection_type || '',
    objection_response: sales.objection_response || '',
    next_step: sales.next_step || 'follow_up',
    reason: sales.reason || '',
    approval_required: Boolean(sales.approval_required),
    human_handoff: Boolean(sales.human_handoff),
    evidence_used: sales.evidence_used || '',
    assistant_message: sales.assistant_message || 'Sales inquiry processed successfully.'
  }
}];

const sales = $('Parse Sales Output').first().json;

return [{
  json: {
    opportunity_id: sales.opportunity_id,
    lead_id: sales.lead_id,
    company_id: sales.company_id,
    chatInput: sales.chatInput,

    intent: sales.intent,
    next_step: sales.next_step,
    approval_required: sales.approval_required === true,
    human_handoff: sales.human_handoff === true,
    assistant_message: sales.assistant_message,
    evidence_used: sales.evidence_used
  }
}];

let raw = '';

try {
  const item = $('Sales agent').first().json;
  raw = item.output || item.text || item.response || item.message || JSON.stringify(item);
} catch (e) {
  raw = $json.output || $json.text || $json.response || '';
}

let text = String(raw || '').trim();

text = text
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const match = text.match(/\{[\s\S]*\}/);

let sales = {};

if (match) {
  try {
    sales = JSON.parse(match[0]);
  } catch (error) {
    sales = { assistant_message: text };
  }
} else {
  sales = {
    assistant_message: text || "Sales request processed successfully."
  };
}

sales.intent = sales.intent || 'sales';
sales.business_need = sales.business_need || '';
sales.pain_points = sales.pain_points || '';
sales.decision_criteria = sales.decision_criteria || '';
sales.stakeholders = sales.stakeholders || '';
sales.matched_solution = sales.matched_solution || '';
sales.objection_type = sales.objection_type || '';
sales.objection_response = sales.objection_response || '';
sales.next_step = sales.next_step || 'follow_up';
sales.reason = sales.reason || '';
sales.approval_required = Boolean(sales.approval_required);
sales.human_handoff = Boolean(sales.human_handoff);
sales.evidence_used = sales.evidence_used || '';
sales.assistant_message = sales.assistant_message || 'Sales inquiry processed.';

return [{ json: sales }];
